class FertilizerStatusBlock(QFrame):
    """Shared compact fertilizer status."""

    def __init__(
        self,
        parent: QWidget | None = None,
    ) -> None:
        super().__init__(parent)
        self.setProperty("fertilizerStatusBlock", True)
        self.setAccessibleName("Magical Fertilizer status")
        self._split_copy = False
        self._leading_widget: QWidget | None = None
        self._action_widget: QWidget | None = None
        self.row = QHBoxLayout(self)
        self.row.setContentsMargins(12, 4, 12, 4)
        self.row.setSpacing(8)
        column = QVBoxLayout()
        column.setContentsMargins(0, 0, 0, 0)
        column.setSpacing(1)
        self.title_label = QLabel("", self)
        self.title_label.setProperty("fertilizerStatusTitle", True)
        self.title_label.hide()
        column.addWidget(self.title_label)
        self.summary_label = QLabel("", self)
        self.summary_label.setProperty("fertilizerStatusSummary", True)
        self.summary_label.setWordWrap(True)
        self.summary_label.setSizePolicy(
            QSizePolicy.Policy.Preferred,
            QSizePolicy.Policy.Fixed,
        )
        apply_tabular_numerals(self.summary_label)
        column.addWidget(self.summary_label)
        self.countdown_progress = QProgressBar(self)
        self.countdown_progress.setProperty(
            "semanticId",
            "garden.fertilizer.remaining",
        )
        self.countdown_progress.setTextVisible(False)
        self.countdown_progress.setFixedHeight(6)
        self.countdown_progress.setAccessibleName(
            "Magical Fertilizer remaining"
        )
        self.countdown_progress.hide()
        column.addWidget(self.countdown_progress)
        self.row.addLayout(column, 1)
        self.active_badge = QLabel("Active", self)
        self.active_badge.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.active_badge.setSizePolicy(
            QSizePolicy.Policy.Maximum,
            QSizePolicy.Policy.Fixed,
        )
        apply_status_chip(self.active_badge, StatusChipTone.ACTIVE)
        self.active_badge.setAccessibleName("Active Magical Fertilizer")
        self.active_badge.hide()
        self.row.addWidget(
            self.active_badge,
            0,
            Qt.AlignmentFlag.AlignTop,
        )
        self._countdown_total = 0
        self.setStyleSheet(
            "QFrame[fertilizerStatusBlock='true'] {"
            f"background:{GARDEN_THEME['raised_surface']}; "
            f"border:1px solid {GARDEN_THEME['subtle_border']}; border-radius:9px;"
            "}"
            f"QLabel[fertilizerStatusTitle='true'] {{color:{GARDEN_THEME['text_primary']}; font-size:14px; font-weight:650;}}"
            f"QLabel[fertilizerStatusSummary='true'] {{color:{GARDEN_THEME['text_secondary']}; font-size:13px; font-weight:600;}}"
            "QLabel[fertilizerStatusSummary='true'][fertilizerUrgent='true'] {"
            f"color:{GARDEN_THEME['danger']}; background:{GARDEN_THEME['danger_soft']}; "
            f"border:1px solid {GARDEN_THEME['danger']}; "
            "border-radius:7px; padding:3px 7px;}"
        )
        self.hide()

    def set_leading_widget(self, widget: QWidget) -> None:
        if self._leading_widget is widget:
            return
        if self._leading_widget is not None:
            self.row.removeWidget(self._leading_widget)
            self._leading_widget.hide()
        self._leading_widget = widget
        widget.setParent(self)
        self.row.insertWidget(
            0,
            widget,
            0,
            Qt.AlignmentFlag.AlignVCenter,
        )
        self._split_copy = True
        self.title_label.show()
        self.updateGeometry()

    def set_action_widget(self, widget: QWidget) -> None:
        """Keep the active status and its one action inside the same card."""

        if self._action_widget is widget:
            return
        if self._action_widget is not None:
            self.row.removeWidget(self._action_widget)
            self._action_widget.hide()
        self._action_widget = widget
        widget.setParent(self)
        badge_index = self.row.indexOf(self.active_badge)
        self.row.insertWidget(
            max(0, badge_index),
            widget,
            0,
            Qt.AlignmentFlag.AlignVCenter,
        )
        self.updateGeometry()

    def set_queued_item(self, item: FertilizerQueueItem | None) -> None:
        """Render the typed next-in-line item without presenting it as active."""

        self.countdown_progress.hide()
        self.active_badge.hide()
        self.setProperty("fertilizerPhase", "queued-next" if item else "inactive")
        self.setProperty("fertilizerQueuedTier", item.tier_id if item else "")
        if item is None:
            self.hide()
            return
        self.title_label.setText("Queued next")
        self.title_label.show()
        predecessor = str(item.starts_after or "active fertilizer")
        noun = "card" if item.cards == 1 else "cards"
        self.summary_label.setText(
            f"{item.name} · Starts after {predecessor} · "
            f"{max(0, int(item.cards)):,} {noun}"
        )
        accessible = f"Queued next: {self.summary_label.text()}"
        self.setAccessibleName("Queued next Magical Fertilizer")
        self.setAccessibleDescription(accessible)
        self.setToolTip(accessible)
        self.show()

    def set_status(self, status: FertilizerStatus | dict[str, Any]) -> None:
        if isinstance(status, dict):
            try:
                status = FertilizerStatus(**status)
            except (TypeError, ValueError):
                self.hide()
                return
        effect = learner_card_copy(status.effect)
        duration = learner_card_copy(status.duration).replace(
            " left",
            " remaining",
        )
        accessible_text = learner_card_copy(status.accessible_text)
        if self._split_copy:
            self.title_label.setText(status.name)
            self.summary_label.setText(
                " · ".join(
                    part for part in (effect, duration) if part
                )
            )
        else:
            self.title_label.setText("")
            self.summary_label.setText(
                " · ".join(
                    part
                    for part in (status.name, effect, duration)
                    if part
                )
            )
        self.summary_label.setProperty(
            "fertilizerUrgent",
            bool(
                status.active
                and status.expires_at_ms is not None
                and 0 < int(status.seconds_remaining) < 60
            ),
        )
        summary_style = self.summary_label.style()
        if summary_style is not None:
            summary_style.unpolish(self.summary_label)
            summary_style.polish(self.summary_label)
        expiry_copy = ""
        if status.active and status.expires_at_epoch_seconds:
            try:
                expiry = datetime.fromtimestamp(
                    int(status.expires_at_epoch_seconds)
                ).astimezone()
                clock = expiry.strftime("%I:%M %p").lstrip("0")
                expiry_copy = f"Ends {expiry.strftime('%b')} {expiry.day} at {clock}"
            except (OSError, OverflowError, TypeError, ValueError):
                expiry_copy = ""
        self.setProperty(
            "fertilizerExpiresAtEpochSeconds",
            status.expires_at_epoch_seconds,
        )
        self.setProperty("fertilizerExpiresAtMs", status.expires_at_ms)
        self.setProperty("fertilizerCardsRemaining", status.cards_remaining)
        self.setProperty("fertilizerQueuedCards", status.queued_cards)
        self.setProperty("fertilizerExpiryCopy", expiry_copy)
        tooltip = ". ".join(
            part.rstrip(".")
            for part in (accessible_text, expiry_copy)
            if part
        )
        if tooltip:
            tooltip += "."
        self.setToolTip(tooltip)
        self.summary_label.setToolTip(tooltip)
        self.setAccessibleDescription(tooltip or accessible_text)
        self.setProperty("fertilizerPhase", status.phase)
        timed_remaining = max(0, int(status.seconds_remaining))
        card_remaining = max(0, int(status.cards_remaining))
        card_total = max(card_remaining, int(status.total_cards))
        if status.active and card_total > 0:
            self._countdown_total = card_total
            self.countdown_progress.setRange(0, card_total)
            self.countdown_progress.setValue(card_remaining)
            self.countdown_progress.setAccessibleDescription(
                duration
            )
            self.countdown_progress.setToolTip("")
        elif status.active and status.expires_at_ms is not None:
            self._countdown_total = max(
                self._countdown_total,
                timed_remaining,
                1,
            )
            self.countdown_progress.setRange(0, self._countdown_total)
            self.countdown_progress.setValue(timed_remaining)
            self.countdown_progress.setAccessibleDescription(
                duration
            )
            self.countdown_progress.setToolTip(expiry_copy)
        else:
            self._countdown_total = 0
            self.countdown_progress.setToolTip("")
        self.countdown_progress.setVisible(
            bool(
                status.active
                and (card_total > 0 or status.expires_at_ms is not None)
            )
        )
        self.active_badge.setVisible(status.active)
        self.setVisible(status.phase != "inactive")


def _button_stylesheet() -> str:
    return button_stylesheet()


def _fit_dialog_to_screen(
    dialog: QDialog,
    default_width: int,
    default_height: int,
    *,
    width_ratio: float = 0.82,
    height_ratio: float = 0.82,
) -> tuple[int, int]:
    """Keep secondary windows useful on compact displays without oversizing large ones."""
    parent = dialog.parent()
    screen = (
        parent.screen()
        if parent is not None and hasattr(parent, "screen")
        else None
    ) or dialog.screen()
    if screen is None:
        return default_width, default_height
    available = screen.availableGeometry()
    return (
        min(default_width, max(dialog.minimumWidth(), int(available.width() * width_ratio))),
        min(default_height, max(dialog.minimumHeight(), int(available.height() * height_ratio))),
    )


class LabeledProgress(QWidget):
    """A numeric label paired with a thin, semantically complete progress bar."""

    def __init__(
        self,
        accessible_name: str = "Progress",
        parent: QWidget | None = None,
        *,
        semantic_id: str = "",
        compact: bool = False,
    ) -> None:
        super().__init__(parent)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(4)
        labels = QHBoxLayout()
        labels.setSpacing(8)
        self.label = QLabel()
        self.label.setWordWrap(True)
        self.value_label = QLabel()
        self.value_label.setProperty("progressValue", True)
        labels.addWidget(self.label, 1)
        labels.addWidget(self.value_label, 0, Qt.AlignmentFlag.AlignRight)
        self.bar = QProgressBar()
        fallback_semantic = "-".join(
            part
            for part in "".join(
                character.casefold()
                if character.isalnum() else " "
                for character in str(accessible_name)
            ).split()
            if part
        )
        self.bar.setProperty(
            "semanticId",
            semantic_id or f"progress.{fallback_semantic or 'value'}",
        )
        self.bar.setProperty(
            "progressVariant",
            "compact" if compact else "standard",
        )
        self.bar.setTextVisible(False)
        self.bar.setFixedHeight(4 if compact else PROGRESS_BAR_HEIGHT)
        self.bar.setAccessibleName(accessible_name)
        set_semantic_role(self.bar, SemanticRole.PROGRESS)
        apply_tabular_numerals(self.value_label)
        layout.addLayout(labels)
        layout.addWidget(self.bar)
        self.supporting_text = QLabel()
        self.supporting_text.setProperty("progressSupportingText", True)
        self.supporting_text.setWordWrap(True)
        self.supporting_text.hide()
        layout.addWidget(self.supporting_text)

    def set_progress(
        self,
        label: str,
        current: int,
        maximum: int,
        *,
        value_text: str | None = None,
        supporting_text: str = "",
    ) -> None:
        current = max(0, int(current))
        maximum = max(1, int(maximum))
        self.label.setText(label)
        self.value_label.setText(value_text or f"{current:,} / {maximum:,}")
        self.bar.setRange(0, maximum)
        self.bar.setValue(min(current, maximum))
        self.supporting_text.setText(str(supporting_text or ""))
        self.supporting_text.setVisible(bool(self.supporting_text.text()))
        description = f"{label}: {self.value_label.text()}"
        if self.supporting_text.text():
            description += f". {self.supporting_text.text()}"
        self.bar.setAccessibleName(label)
        self.bar.setAccessibleDescription(description)
        self.setAccessibleName(description)


class ProgressBar(LabeledProgress):
    """Shared stage-relative Growth progress presentation."""


GardenProgressBar = ProgressBar
ProgressMeter = ProgressBar
GardenProgressMeter = ProgressBar


class GardenTabs(QTabWidget):
    """Shared accessible tab container with unclipped, scrollable labels."""

    def __init__(self, accessible_name: str, parent: QWidget | None = None) -> None:
        super().__init__(parent)
        self.setDocumentMode(True)
        self.setAccessibleName(accessible_name)
        set_semantic_role(self.tabBar(), SemanticRole.TABS)
        self.tabBar().setUsesScrollButtons(False)
        self.tabBar().setExpanding(True)
        self.tabBar().setElideMode(Qt.TextElideMode.ElideNone)
        self.setSizePolicy(
            QSizePolicy.Policy.Expanding,
            QSizePolicy.Policy.Preferred,
        )
        self.currentChanged.connect(self._schedule_dialog_refit)

    def _sync_tab_overflow(self) -> None:
        bar = self.tabBar()
        if bool(self.property("forceTabFit")):
            bar.setExpanding(True)
            bar.setUsesScrollButtons(False)
            bar.setProperty("tabOverflow", "fit")
            return
        required = sum(
            max(
                64,
                bar.fontMetrics().horizontalAdvance(self.tabText(index)) + 16,
            )
            for index in range(self.count())
            if bar.isTabVisible(index)
        )
        scrollable = required > max(1, int(bar.width()))
        bar.setExpanding(not scrollable)
        bar.setUsesScrollButtons(scrollable)
        bar.setProperty("tabOverflow", "scroll" if scrollable else "fit")

    def _current_page_hint(self, *, minimum: bool) -> QSize:
        """Measure the active page instead of the tallest hidden tab.

        Qt's default QTabWidget hint is the union of every page. That makes a
        one-row or completion tab inherit the catalogue tab's height and was
        the source of several large internal blank regions in the review set.
        """

        inherited = (
            super().minimumSizeHint()
            if minimum
            else super().sizeHint()
        )
        page = self.currentWidget()
        if page is None:
            return inherited
        page_hint = page.minimumSizeHint() if minimum else page.sizeHint()
        tab_height = max(
            int(self.tabBar().minimumSizeHint().height()),
            int(self.tabBar().sizeHint().height()),
        )
        return QSize(
            max(1, int(inherited.width())),
            max(1, int(page_hint.height()) + tab_height + 4),
        )

    def sizeHint(self) -> QSize:
        return self._current_page_hint(minimum=False)

    def minimumSizeHint(self) -> QSize:
        return self._current_page_hint(minimum=True)

    def resizeEvent(self, event: Any) -> None:
        super().resizeEvent(event)
        self._sync_tab_overflow()

    def _schedule_dialog_refit(self, _index: int) -> None:
        self._sync_tab_overflow()
        owner = self.window()
        if isinstance(owner, DialogShell):
            owner.schedule_content_fit("tab-change", preserve_transition=False)


GardenTabBar = GardenTabs


class NurseryCatalogTabs(QWidget):
    """Four fixed segments that deliberately reflow from one row to two."""

    currentChanged = pyqtSignal(int)

    def __init__(
        self,
        accessible_name: str,
        parent: QWidget | None = None,
    ) -> None:
        super().__init__(parent)
        self.setAccessibleName(accessible_name)
        self.setProperty("nurserySegmentedTabs", True)
        self.setSizePolicy(
            QSizePolicy.Policy.Expanding,
            QSizePolicy.Policy.Expanding,
        )
        self._pages: list[QWidget] = []
        self._buttons: list[QPushButton] = []
        self._tab_texts: list[str] = []
        self._tab_rows = 1
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)
        self._bar = QWidget(self)
        self._bar.setProperty("gardenRole", SemanticRole.TABS.value)
        self._bar.setProperty("nurserySegmentedBar", True)
        self._bar_grid = QGridLayout(self._bar)
        self._bar_grid.setContentsMargins(0, 0, 0, 0)
        self._bar_grid.setHorizontalSpacing(2)
        self._bar_grid.setVerticalSpacing(2)
        self._bar.setFixedHeight(TAB_VISUAL_HEIGHT)
        layout.addWidget(self._bar)
        self._stack = QStackedWidget(self)
        self._stack.setSizePolicy(
            QSizePolicy.Policy.Expanding,
            QSizePolicy.Policy.Expanding,
        )
        self._stack.currentChanged.connect(self._handle_current_changed)
        layout.addWidget(self._stack, 1)

    def setDocumentMode(self, enabled: bool) -> None:
        self.setProperty("documentMode", bool(enabled))

    def addTab(self, page: QWidget, label: str) -> int:
        index = len(self._pages)
        visible_label = str(label).replace("&&", "&")
        button_label = visible_label.replace("&", "&&")
        self._pages.append(page)
        self._tab_texts.append(visible_label)
        self._stack.addWidget(page)
        button = QPushButton(button_label, self._bar)
        button.setCheckable(True)
        button.setAutoExclusive(True)
        button.setProperty("nurserySegment", True)
        button.setProperty("tabIndex", index)
        button.setProperty(
            "nurserySegmentState",
            "active" if index == self.currentIndex() else "inactive",
        )
        button.setCursor(Qt.CursorShape.PointingHandCursor)
        button.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        button.setMinimumWidth(0)
        button.setSizePolicy(
            QSizePolicy.Policy.Expanding,
            QSizePolicy.Policy.Fixed,
        )
        button.setAccessibleName(f"{visible_label} tab")
        button.clicked.connect(
            lambda _checked=False, selected=index: self.setCurrentIndex(selected)
        )
        self._buttons.append(button)
        self._reflow_tabs()
        if index == 0:
            self._stack.setCurrentIndex(0)
            button.setChecked(True)
        return index

    def count(self) -> int:
        return len(self._pages)

    def widget(self, index: int) -> QWidget | None:
        return self._pages[index] if 0 <= int(index) < len(self._pages) else None

    def currentWidget(self) -> QWidget | None:
        return self._stack.currentWidget()

    def currentIndex(self) -> int:
        return int(self._stack.currentIndex())

    def setCurrentIndex(self, index: int) -> None:
        selected = int(index)
        if not 0 <= selected < len(self._pages):
            return
        if self._buttons[selected].isHidden() or not self._buttons[selected].isEnabled():
            return
        self._stack.setCurrentIndex(selected)

    def setCurrentWidget(self, page: QWidget) -> None:
        index = self._stack.indexOf(page)
        if index >= 0:
            self.setCurrentIndex(index)

    def setTabEnabled(self, index: int, enabled: bool) -> None:
        if 0 <= int(index) < len(self._buttons):
            self._buttons[int(index)].setEnabled(bool(enabled))

    def setTabVisible(self, index: int, visible: bool) -> None:
        if 0 <= int(index) < len(self._buttons):
            self._buttons[int(index)].setVisible(bool(visible))
            self._reflow_tabs()

    def setTabToolTip(self, index: int, text: str) -> None:
        if 0 <= int(index) < len(self._buttons):
            self._buttons[int(index)].setToolTip(str(text))

    def tabText(self, index: int) -> str:
        return self._tab_texts[int(index)]

    def tabBar(self) -> QWidget:
        return self._bar

    def setFocus(self, reason: Any = Qt.FocusReason.OtherFocusReason) -> None:
        index = max(0, self.currentIndex())
        if index < len(self._buttons):
            self._buttons[index].setFocus(reason)
            return
        super().setFocus(reason)

    def _handle_current_changed(self, index: int) -> None:
        for button_index, button in enumerate(self._buttons):
            button.setChecked(button_index == int(index))
            button.setProperty(
                "nurserySegmentState",
                "active" if button_index == int(index) else "inactive",
            )
            style = button.style()
            if style is not None:
                style.unpolish(button)
                style.polish(button)
        self.currentChanged.emit(int(index))
        owner = self.window()
        if isinstance(owner, DialogShell):
            owner.schedule_content_fit("nursery-tab-change", preserve_transition=False)

    def _one_row_minimum_width(self) -> int:
        metrics = self._bar.fontMetrics()
        widths = [
            max(104, int(metrics.horizontalAdvance(label)) + 28)
            for label, button in zip(self._tab_texts, self._buttons)
            if not button.isHidden()
        ]
        return (
            max(widths, default=104) * len(widths)
            + max(0, len(widths) - 1) * self._bar_grid.horizontalSpacing()
        )

    def _reflow_tabs(self) -> None:
        visible_buttons = [button for button in self._buttons if not button.isHidden()]
        target_rows = (
            2
            if len(visible_buttons) > 2
            and max(1, int(self._bar.width() or self.width())) < self._one_row_minimum_width()
            else 1
        )
        while self._bar_grid.count():
            self._bar_grid.takeAt(0)
        columns = 2 if target_rows == 2 else max(1, len(visible_buttons))
        metrics = self._bar.fontMetrics()
        segment_minimum = max(
            (
                max(
                    104,
                    int(metrics.horizontalAdvance(self._tab_texts[
                        int(button.property("tabIndex") or 0)
                    ])) + 28,
                )
                for button in visible_buttons
            ),
            default=104,
        )
        for visible_index, button in enumerate(visible_buttons):
            self._bar_grid.addWidget(
                button,
                visible_index // columns,
                visible_index % columns,
            )
        for column in range(4):
            self._bar_grid.setColumnMinimumWidth(column, 0)
            self._bar_grid.setColumnStretch(column, 0)
        for column in range(max(1, columns)):
            self._bar_grid.setColumnMinimumWidth(column, segment_minimum)
            self._bar_grid.setColumnStretch(column, 1)
        self._tab_rows = target_rows
        self._bar.setProperty("nurseryTabRows", target_rows)
        self.setProperty("nurseryTabRows", target_rows)
        self._bar.setFixedHeight(TAB_VISUAL_HEIGHT * target_rows + max(0, target_rows - 1) * 2)
        self._bar.updateGeometry()

    def resizeEvent(self, event: Any) -> None:
        super().resizeEvent(event)
        self._reflow_tabs()


