class DisclosureRow(QWidget):
    """Keyboard-native disclosure with visible state and no independent scrolling."""

    def __init__(
        self,
        title: str,
        rows: list[tuple[str, str]],
        *,
        semantic_id: str = "",
        row_ids: tuple[str, ...] = (),
        expanded: bool = False,
        compact: bool = False,
        parent: QWidget | None = None,
    ) -> None:
        super().__init__(parent)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(4)
        self.button = QPushButton()
        self.button.setCheckable(True)
        self.button.setChecked(expanded)
        self.button.setProperty("disclosureRow", True)
        self.button.setProperty("compactDisclosure", bool(compact))
        if compact:
            self.button.setSizePolicy(
                QSizePolicy.Policy.Maximum,
                QSizePolicy.Policy.Fixed,
            )
        set_semantic_role(self.button, SemanticRole.DISCLOSURE)
        self.button.setCursor(Qt.CursorShape.PointingHandCursor)
        self.panel = QWidget()
        panel_layout = QVBoxLayout(self.panel)
        panel_layout.setContentsMargins(12, 4, 4, 8)
        panel_layout.setSpacing(4)
        if row_ids and len(row_ids) != len(rows):
            raise ValueError("disclosure row IDs must match disclosure rows")
        if semantic_id:
            self.setProperty("semanticId", semantic_id)
            self.setAccessibleName(semantic_id)
        for row_index, (label_text, value_text) in enumerate(rows):
            row_id = row_ids[row_index] if row_ids else ""
            row = QHBoxLayout()
            label = QLabel(label_text)
            label.setWordWrap(True)
            value = QLabel(value_text)
            value.setWordWrap(True)
            if row_id:
                label.setProperty("disclosureRowId", row_id)
                label.setProperty("disclosureRowRole", "label")
                label.setAccessibleName(f"{semantic_id}:{row_id}:label")
                value.setProperty("disclosureRowId", row_id)
                value.setProperty("disclosureRowRole", "value")
                value.setAccessibleName(f"{semantic_id}:{row_id}:value")
            value.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
            apply_tabular_numerals(value)
            row.addWidget(label, 1)
            row.addWidget(value, 0)
            panel_layout.addLayout(row)
        layout.addWidget(self.button)
        layout.addWidget(self.panel)

        def sync_compact_width() -> None:
            if not compact:
                return
            # Re-measure after the inherited dialog stylesheet has polished
            # the button. At construction time Qt still reports the smaller
            # platform-default font, while the painted control uses the
            # Garden semibold button font.
            self.button.ensurePolished()
            styled_text_width = int(
                self.button.fontMetrics().horizontalAdvance(title)
            )
            self.button.setMinimumWidth(max(
                int(self.button.minimumWidth()),
                styled_text_width + 46,
            ))

        def sync(checked: bool) -> None:
            self.button.setText(title)
            self.button.setIcon(
                garden_icon(
                    "chevron-down" if checked else "chevron-right",
                    color=GARDEN_THEME["text_secondary"],
                )
            )
            self.button.setIconSize(QSize(16, 16))
            self.button.setAccessibleName(title)
            self.button.setAccessibleDescription(
                f"{title}. {'Expanded' if checked else 'Collapsed'}."
            )
            if compact:
                # Reserve the 16 px SVG, 8 px icon gap, 16 px horizontal
                # padding, and a post-style font/raster buffer. The dialog's
                # inherited button style applies a larger semibold font after
                # this row is constructed, so the pre-style font metrics need
                # enough room for that native macOS width increase.
                self.button.setMinimumWidth(
                    self.button.fontMetrics().horizontalAdvance(title) + 68
                )
                QTimer.singleShot(0, sync_compact_width)
            self.panel.setVisible(checked)

        self.button.toggled.connect(sync)
        sync(expanded)


